package com.bakeflow.identity;
import static com.bakeflow.identity.IdentityDtos.*;import jakarta.servlet.http.*;import java.time.Duration;import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/auth") public class AuthController{private static final String COOKIE="bakeflow_refresh";private final IdentityService service;private final boolean secure;private final Duration ttl;private final Set<String>origins;public AuthController(IdentityService service,@Value("${security.cookie-secure}")boolean secure,@Value("${security.refresh-token-ttl}")Duration ttl,@Value("${security.allowed-origins}")List<String>origins){this.service=service;this.secure=secure;this.ttl=ttl;this.origins=Set.copyOf(origins);}@PostMapping("/login")ResponseEntity<TokenResponse>login(@RequestBody LoginInput in,HttpServletRequest req){return withCookie(service.login(in,req.getRemoteAddr(),req.getHeader("User-Agent")));}@PostMapping("/refresh")ResponseEntity<TokenResponse>refresh(HttpServletRequest req){origin(req);return withCookie(service.refresh(cookie(req),req.getHeader("User-Agent")));}@PostMapping("/logout")ResponseEntity<Void>logout(HttpServletRequest req){origin(req);service.logout(cookie(req));return ResponseEntity.noContent().header(HttpHeaders.SET_COOKIE,clear()).build();}@PostMapping("/logout-all")ResponseEntity<Void>logoutAll(HttpServletRequest req){origin(req);service.logoutAll(required());return ResponseEntity.noContent().header(HttpHeaders.SET_COOKIE,clear()).build();}@GetMapping("/me")UserView me(){return service.me(required());}@GetMapping("/sessions")List<SessionView>sessions(HttpServletRequest req){String raw=cookie(req);return service.sessions(required(),raw==null?null:IdentityService.sha(raw));}@DeleteMapping("/sessions/{id}")void revoke(@PathVariable UUID id){service.revokeSession(required(),id);}@PostMapping("/change-password")void password(@RequestBody PasswordChange in,HttpServletRequest req){origin(req);service.changePassword(required(),in,cookie(req));}private ResponseEntity<TokenResponse>withCookie(IdentityService.TokenPair p){return ResponseEntity.ok().header(HttpHeaders.SET_COOKIE,ResponseCookie.from(COOKIE,p.refreshToken()).httpOnly(true).secure(secure).sameSite("Strict").path("/api/v1/auth").maxAge(ttl).build().toString()).body(p.response());}private String clear(){return ResponseCookie.from(COOKIE,"").httpOnly(true).secure(secure).sameSite("Strict").path("/api/v1/auth").maxAge(Duration.ZERO).build().toString();}private String cookie(HttpServletRequest r){if(r.getCookies()!=null)for(Cookie c:r.getCookies())if(COOKIE.equals(c.getName()))return c.getValue();return null;}private UUID required(){UUID id=SecuritySupport.currentUserId();if(id==null)throw new IdentityException("UNAUTHENTICATED");return id;}private void origin(HttpServletRequest r){String origin=r.getHeader("Origin");if(origin!=null&&!origins.contains(origin))throw new IdentityException("INVALID_ORIGIN");}}
